:root {
  --ink: #202034;
  --paper: #fffdf7;
  --panel: #f0ecff;
  --violet: #6547d7;
  --lime: #b7e755;
  --coral: #fa6a58;
  --line: #d8d1ee;
  --muted: #77738c;
}

* {
  box-sizing: border-box;
}

.match-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.match-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 2px solid var(--ink);
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--paper);
  background: var(--violet);
  border: 2px solid var(--ink);
  border-radius: 10px;
  font-size: 20px;
}

.kicker {
  margin: 0 0 2px;
  color: var(--violet);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.match-header h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1;
  letter-spacing: -0.4px;
}

.status {
  padding: 5px 8px;
  color: var(--ink);
  background: var(--lime);
  border: 2px solid var(--ink);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.8px;
}

.scoreboard {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  padding: 12px 16px;
  background: var(--panel);
}

.player {
  padding: 11px 12px 10px;
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 12px;
}

.player.challenger {
  border-color: var(--violet);
}

.player-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.seed {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.ball {
  color: var(--coral);
  font-size: 15px;
  line-height: 1;
}

.ball.muted {
  color: var(--line);
}

.player-name {
  margin: 10px 0 2px;
  font-size: 14px;
  font-weight: 750;
}

.score {
  margin: 0;
  color: var(--violet);
  font-size: 24px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.8px;
}

.score small {
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.5px;
}

.match-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 16px;
}

.round {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.35px;
}

.round span {
  color: var(--coral);
}

.match-footer button {
  flex: 0 0 auto;
  padding: 7px 10px;
  color: var(--paper);
  background: var(--ink);
  border: 0;
  border-radius: 8px;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
}
